INSERT INTO visita (id,uuid,criado_em,unidade_id,ciclo_id,data_visita,data_aproximada,tipo,situacao,origem,observacao_importacao) VALUES (1,'hist-0001','2026-10-03 00:00:00',34,1,'2023-11-21',0,'ordinaria','concluida','Planilha: Performance Unidades 2023 (linha 7) + Avaliação Global',NULL);
INSERT INTO avaliacao_item (visita_id,item_id,pontuacao,nao_se_aplica) VALUES (1,1,1,0),(1,2,1,0),(1,3,1,0),(1,4,2,0),(1,5,1,0),(1,6,1,0),(1,7,2,0),(1,8,1,0),(1,9,2,0),(1,10,1,0),(1,11,2,0),(1,12,1,0),(1,13,2,0),(1,14,2,0);
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (1,1,'Infiltrações em teto, fechaduras de portas e banheiro quebradas; baixa segurança predial com furto recente de 10 CPUs. Encontradas lâmpadas queimadas, geladeira de vacinas e medicamentos aguardando conserto há aproximadamente 1 ano.Sem ar condicionado e com incidência de raios solares em consultório odontológico. Rede de gases não funcionante.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (1,2,'Indicadores de gestão não disponíveis. Falta de integração com Núcleo de Especialidades e serviços de Urgência. Bom controle de agendas com baixo absenteísmo. Territorialização adequada e divulgada.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (1,3,'Plano Municipal com execução em andamento, mas não completa em itens ligados à estrutura e integração entre serviços.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (1,4,'Evidências de boa satisfação dos usuários.');
INSERT INTO visita (id,uuid,criado_em,unidade_id,ciclo_id,data_visita,data_aproximada,tipo,situacao,origem,observacao_importacao) VALUES (2,'hist-0002','2026-10-03 00:00:00',30,1,'2023-12-11',0,'ordinaria','concluida','Planilha: Performance Unidades 2023 (linha 8) + Avaliação Global',NULL);
INSERT INTO avaliacao_item (visita_id,item_id,pontuacao,nao_se_aplica) VALUES (2,1,1,0),(2,2,2,0),(2,3,0,0),(2,4,2,0),(2,5,1,0),(2,6,1,0),(2,7,1,0),(2,8,1,0),(2,9,2,0),(2,10,1,0),(2,11,1,0),(2,12,1,0),(2,13,2,0),(2,14,1,0);
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (2,1,'Aparelho ECG sem funcionar (sem peras) e pacientes vão ao Jd. São Paulo; rede de gases não funciona há 1,5 ano, não possui desfibrilador. Há falta de vacinas.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (2,2,'Unidade com baixo absenteísmo. Não possui farmácia e transfere pacientes para medicamentos no Jd. São Paulo.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (2,3,'Alguns indicadores do Plano Municipals de Saúde não são conhecidos na Unidade');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (2,4,'População que estava no local durante a visita mostra satisfação com atendimento');
