INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (4,2,'Unidade é UBS e ESF, mas equipe de saúde da Família não tem médico. Gerente da Unidade presente apenas às 5as.-feiras. Ginecologista apenas 1 período na semana. Equipe conhece o território e faz visitas aos usuários apesar de apenas 1 agente disponível no momento.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (4,3,'Não foi possível evidenciar o cumprimento dos indicadores do Plano Municipal de Saúde pela ausência da gerente. Há evidência de pouca integração entre serviços.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (4,4,'Usuários entrevistados mostraram-se satisfeitos com o  estabelecimento.');
