INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (14,1,'Predio com infiltrações e goteiras importantes. Telhado com problemas, Lixo não recolhido na área externa. Medicamentos deixados em cima da maca e em armário aberto. Almoxarifado sem organização. Garrafas pet na área externa.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (14,2,'Coordenadora nova no local ainda sem domínio dos indicadores. Alto abasenteísmo sem trabalho para contenção. Não ecidenciados treinamentos da equipe.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (14,3,'Dificuldade em entendimento e cumprimento dos indicadores constantes no Plano Municipal de Saúde');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (14,4,'Sem evidências de reclamações no momento. Não havia usuários presentes na visita.');
