INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (15,1,'Unidade reformada, mas com salas sem condições de uso, recepção pequena e fluxo confuso para usuários. Salas de arquivos desorganizadas e insuficientes.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (15,2,'Indicadores de gestão em início de utilização. Dificuldades com médicos especialistas, Sem evidência de cronograma de treinamentos. Assiustentes sociais empenhadas na resolução de problemas dos usuários!');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (15,3,'Plano Municipal em andamentoporém sem demonstração de integração com outras unidades de saúde. Marcação de consultas confusa pela quantidade de sistemas.');
INSERT INTO comentario_dimensao (visita_id,dimensao_id,texto) VALUES (15,4,'Reclamações frequentes por vagas registradas no COMSAUDE. Usuários insatisfeitos com demora em exames e consultas.');
